//! Shared semantic and explicit performance inputs for representation cancellation.
use nash_ir::{
    build::Builder,
    core::*,
    ty::{ConstTy, Ty},
};
use nash_plutus::{
    builtin::DefaultFunction as F, constant::Constant, data::PlutusData as D, typ::Type,
};

pub fn cases<'a>(b: &Builder<'a>) -> Vec<(String, &'a Core<'a>, bool)> {
    let a = b.arena;
    let d = D::integer_from(a, 7);
    let data = Constant::data(a, d);
    let pair = Constant::proto_pair(a, &Type::Data, &Type::Data, data, data);
    let list = Constant::proto_list(a, &Type::Data, a.alloc([data]));
    let map = Constant::proto_list(
        a,
        a.alloc(Type::Pair(&Type::Data, &Type::Data)),
        a.alloc([pair]),
    );
    let mut cases = Vec::new();
    for (name, encode, decode, value, encoded) in [
        ("integer", F::IData, F::UnIData, b.int(7), b.lit(data)),
        (
            "bytes",
            F::BData,
            F::UnBData,
            b.lit(Constant::byte_string(a, b"hello")),
            b.lit(Constant::data(a, D::byte_string(a, b"hello"))),
        ),
        (
            "list",
            F::ListData,
            F::UnListData,
            b.lit(list),
            b.lit(Constant::data(a, D::list(a, a.alloc([d])))),
        ),
        (
            "map",
            F::MapData,
            F::UnMapData,
            b.lit(map),
            b.lit(Constant::data(a, D::map(a, a.alloc([(d, d)])))),
        ),
        (
            "utf8",
            F::EncodeUtf8,
            F::DecodeUtf8,
            b.lit(Constant::string(a, "héllo")),
            b.lit(Constant::byte_string(a, "héllo".as_bytes())),
        ),
    ] {
        let wrap = |x| b.builtin(decode, &[b.builtin(encode, &[x], encoded.ty)], value.ty);
        let trace = |s, x| b.trace(b.lit(Constant::string(a, s)), x);
        cases.push((format!("{name}_direct"), wrap(value), false));
        cases.push((
            format!("{name}_trace"),
            wrap(trace("operand", value)),
            false,
        ));
        cases.push((
            format!("{name}_decoded"),
            wrap(b.builtin(decode, &[encoded], value.ty)),
            false,
        ));
        cases.push((
            format!("{name}_decode_failure"),
            wrap(b.builtin(decode, &[b.int(0)], value.ty)),
            true,
        ));
        cases.push((
            format!("{name}_reverse"),
            b.builtin(
                encode,
                &[b.builtin(decode, &[encoded], value.ty)],
                encoded.ty,
            ),
            false,
        ));
        cases.push((
            format!("{name}_wrong_kind"),
            wrap(b.with_type(b.lit(Constant::bool(a, false)), value.ty)),
            true,
        ));
        cases.push((
            format!("{name}_cold"),
            b.if_(
                b.lit(Constant::bool(a, true)),
                value,
                wrap(trace("cold", value)),
            ),
            false,
        ));
        let x = Binder {
            name: b.fresh("x"),
            ty: value.ty,
        };
        let y = Binder {
            name: b.fresh("encoded"),
            ty: encoded.ty,
        };
        let z = Binder {
            name: b.fresh("alias"),
            ty: encoded.ty,
        };
        let decoded = b.builtin(decode, &[b.var(z.name, z.ty)], value.ty);
        let bindings = |body| {
            b.let_(
                x,
                trace("once", value),
                b.let_(
                    y,
                    b.builtin(encode, &[b.var(x.name, x.ty)], encoded.ty),
                    b.let_(z, b.var(y.name, y.ty), body),
                ),
            )
        };
        cases.push((
            format!("{name}_bound"),
            bindings(trace("after encoding", decoded)),
            false,
        ));
        cases.push((
            format!("{name}_captured"),
            bindings(b.force(b.delay(decoded), decoded.ty)),
            false,
        ));
        cases.push((
            format!("{name}_escaping"),
            bindings(b.constr(0, &[b.var(y.name, y.ty), decoded, decoded], Ty::Erased)),
            false,
        ));
        cases.push((
            format!("{name}_bound_invalid"),
            b.let_(
                x,
                trace(
                    "operand",
                    b.with_type(b.lit(Constant::bool(a, false)), value.ty),
                ),
                b.let_(
                    y,
                    b.builtin(encode, &[b.var(x.name, x.ty)], encoded.ty),
                    trace(
                        "must not run",
                        b.builtin(decode, &[b.var(y.name, y.ty)], value.ty),
                    ),
                ),
            ),
            true,
        ));
        cases.push((
            format!("{name}_reverse_bound_invalid"),
            b.let_(
                y,
                b.with_type(b.int(0), encoded.ty),
                b.let_(
                    x,
                    b.builtin(decode, &[b.var(y.name, y.ty)], value.ty),
                    trace(
                        "must not run",
                        b.builtin(encode, &[b.var(x.name, x.ty)], encoded.ty),
                    ),
                ),
            ),
            true,
        ));
        cases.push((
            format!("{name}_oversaturated"),
            b.app(wrap(value), &[b.int(1)], value.ty),
            true,
        ));
        let unknown = Binder {
            name: b.fresh("unknown"),
            ty: value.ty,
        };
        cases.push((
            format!("{name}_unknown_invalid"),
            b.app(
                b.lam(&[unknown], wrap(b.var(unknown.name, unknown.ty))),
                &[b.lit(Constant::bool(a, false))],
                value.ty,
            ),
            true,
        ));
        cases.push((
            format!("{name}_partial"),
            b.app(
                b.builtin(decode, &[], Ty::Erased),
                &[b.builtin(encode, &[value], encoded.ty)],
                value.ty,
            ),
            false,
        ));
    }
    let bad_utf8 = b.lit(Constant::byte_string(a, &[255]));
    cases.push((
        "utf8_reverse_invalid".into(),
        b.builtin(
            F::EncodeUtf8,
            &[b.builtin(F::DecodeUtf8, &[bad_utf8], Ty::Const(&ConstTy::String))],
            bad_utf8.ty,
        ),
        true,
    ));
    for (name, encode, decode, typ) in [
        ("list_wrong_tag", F::ListData, F::UnListData, &Type::Integer),
        ("map_wrong_tag", F::MapData, F::UnMapData, &Type::Data),
    ] {
        let value = b.lit(Constant::proto_list(a, typ, &[]));
        cases.push((
            name.into(),
            b.builtin(decode, &[b.builtin(encode, &[value], Ty::Erased)], value.ty),
            true,
        ));
    }
    let data_ty = b.lit(data).ty;
    let fields = Binder {
        name: b.fresh("fields"),
        ty: b.lit(list).ty,
    };
    let tag = Binder {
        name: b.fresh("tag"),
        ty: b.int(0).ty,
    };
    let encoded = Binder {
        name: b.fresh("constructor"),
        ty: data_ty,
    };
    let payload = Binder {
        name: b.fresh("payload"),
        ty: Ty::Erased,
    };
    let p = b.var(payload.name, payload.ty);
    let fst = b.builtin(F::FstPair, &[p], tag.ty);
    let snd = b.builtin(F::SndPair, &[p], fields.ty);
    let constructor = b.builtin(
        F::ConstrData,
        &[b.var(tag.name, tag.ty), b.var(fields.name, fields.ty)],
        data_ty,
    );
    let bind = |body| {
        b.let_(
            tag,
            b.int(0),
            b.let_(
                fields,
                b.lit(list),
                b.let_(
                    encoded,
                    constructor,
                    b.let_(
                        payload,
                        b.builtin(
                            F::UnConstrData,
                            &[b.var(encoded.name, encoded.ty)],
                            Ty::Erased,
                        ),
                        body,
                    ),
                ),
            ),
        )
    };
    cases.push(("constructor_tag".into(), bind(fst), false));
    cases.push(("constructor_fields".into(), bind(snd), false));
    cases.push((
        "constructor_rebuild".into(),
        bind(b.builtin(F::ConstrData, &[fst, snd], data_ty)),
        false,
    ));
    for (name, subject, fails) in [
        (
            "constructor_known_reverse",
            b.lit(Constant::data(a, D::constr(a, 3, a.alloc([d])))),
            false,
        ),
        ("constructor_wrong_variant", b.lit(data), true),
    ] {
        cases.push((
            name.into(),
            b.let_(
                encoded,
                subject,
                b.let_(
                    payload,
                    b.builtin(F::UnConstrData, &[b.var(encoded.name, data_ty)], Ty::Erased),
                    b.trace(
                        b.lit(Constant::string(a, "after decoding")),
                        b.builtin(F::ConstrData, &[fst, snd], data_ty),
                    ),
                ),
            ),
            fails,
        ));
    }
    let bad_tag = b.with_type(b.lit(Constant::bool(a, false)), tag.ty);
    cases.push((
        "constructor_bad_tag".into(),
        b.let_(
            tag,
            bad_tag,
            b.let_(
                fields,
                b.trace(b.lit(Constant::string(a, "fields evaluated")), b.lit(list)),
                b.let_(
                    encoded,
                    constructor,
                    b.builtin(
                        F::FstPair,
                        &[b.builtin(F::UnConstrData, &[b.var(encoded.name, data_ty)], Ty::Erased)],
                        tag.ty,
                    ),
                ),
            ),
        ),
        true,
    ));
    cases.push((
        "constructor_bad_fields".into(),
        b.let_(
            tag,
            b.int(0),
            b.let_(
                fields,
                b.with_type(b.lit(Constant::bool(a, false)), fields.ty),
                b.let_(
                    encoded,
                    constructor,
                    b.builtin(
                        F::SndPair,
                        &[b.builtin(F::UnConstrData, &[b.var(encoded.name, data_ty)], Ty::Erased)],
                        fields.ty,
                    ),
                ),
            ),
        ),
        true,
    ));
    cases
}

sources.PairInputs:
//! Inputs shared by pair-projection snapshots and explicit measurements.
use nash_ir::{
    build::Builder,
    core::*,
    ty::{ConstTy, Ty},
};
use nash_plutus::{
    builtin::DefaultFunction as F, constant::Constant as C, data::PlutusData as D, typ::Type,
};

pub fn cases<'a>(b: &Builder<'a>) -> Vec<(String, &'a Core<'a>, bool)> {
    let a = b.arena;
    let int = b.int(0).ty;
    let pair = b.lit(C::proto_pair(
        a,
        &Type::Integer,
        &Type::Integer,
        C::integer_from(a, 7),
        C::integer_from(a, 8),
    ));
    let data = b.lit(C::data(a, D::integer_from(a, 7)));
    let made = b.builtin(
        F::MkPairData,
        &[data, data],
        Ty::Const(a.alloc(ConstTy::Pair(data.ty, data.ty))),
    );
    let unwrapped = b.builtin(
        F::UnConstrData,
        &[b.lit(C::data(a, D::constr(a, 0, &[])))],
        Ty::Const(a.alloc(ConstTy::Pair(
            int,
            Ty::Const(a.alloc(ConstTy::List(data.ty))),
        ))),
    );
    let trace = |s, x| b.trace(b.lit(C::string(a, s)), x);
    let mut cases = Vec::new();
    for (name, subject, left_ty, right_ty, fails) in [
        ("literal", pair, int, int, false),
        ("traced", trace("subject", pair), int, int, false),
        ("made_data", made, data.ty, data.ty, false),
        (
            "decoded",
            unwrapped,
            int,
            Ty::Const(a.alloc(ConstTy::List(data.ty))),
            false,
        ),
        (
            "bad_decoder",
            b.builtin(F::UnConstrData, &[data], unwrapped.ty),
            int,
            Ty::Const(a.alloc(ConstTy::List(data.ty))),
            true,
        ),
        (
            "ignored_failure",
            b.builtin(
                F::MkPairData,
                &[data, trace("unused field", b.error(data.ty))],
                made.ty,
            ),
            data.ty,
            data.ty,
            true,
        ),
        (
            "wrong_subject",
            b.with_type(b.int(1), pair.ty),
            int,
            int,
            true,
        ),
        // Generic UPLC case accepts this, whereas fstPair would reject it.
        (
            "native_constructor",
            b.with_type(b.constr(0, &[b.int(7), b.int(8)], Ty::Erased), pair.ty),
            int,
            int,
            false,
        ),
    ] {
        for second in [false, true] {
            let x = Binder {
                name: b.fresh("x"),
                ty: left_ty,
            };
            let y = Binder {
                name: b.fresh("y"),
                ty: right_ty,
            };
            let selected = if second { y } else { x };
            let value = b.var(selected.name, selected.ty);
            let core = b.case(
                CaseKind::Pair,
                subject,
                &[Branch {
                    test: Test::Pair,
                    binders: a.alloc([x, y]),
                    body: value,
                }],
                None,
                value.ty,
            );
            cases.push((
                format!("{name}_{}", if second { "second" } else { "first" }),
                core,
                fails,
            ));
        }
    }
    for mode in ["body", "both", "neither", "delay", "lambda", "repeated"] {
        let x = Binder {
            name: b.fresh("x"),
            ty: int,
        };
        let y = Binder {
            name: b.fresh("y"),
            ty: int,
        };
        let xv = b.var(x.name, x.ty);
        let body = match mode {
            "both" => b.builtin(F::AddInteger, &[xv, b.var(y.name, y.ty)], int),
            "neither" => b.int(42),
            "delay" => b.delay(xv),
            "lambda" => b.lam(
                &[Binder {
                    name: b.fresh("unused"),
                    ty: int,
                }],
                xv,
            ),
            "repeated" => b.builtin(F::AddInteger, &[xv, xv], int),
            _ => trace("body", b.builtin(F::AddInteger, &[xv, b.int(1)], int)),
        };
        let core = b.case(
            CaseKind::Pair,
            trace("subject", pair),
            &[Branch {
                test: Test::Pair,
                binders: a.alloc([x, y]),
                body,
            }],
            None,
            body.ty,
        );
        // Force/application is after the case, exposing any misplaced strict work.
        let core = match mode {
            "delay" => b.force(core, int),
            "lambda" => b.app(core, &[trace("argument", b.int(0))], int),
            _ => core,
        };
        cases.push((mode.into(), core, false));
    }
    for second in [false, true] {
        let select = |subject| {
            let x = Binder {
                name: b.fresh("x"),
                ty: int,
            };
            let y = Binder {
                name: b.fresh("y"),
                ty: int,
            };
            let selected = if second { y } else { x };
            b.case(
                CaseKind::Pair,
                subject,
                &[Branch {
                    test: Test::Pair,
                    binders: a.alloc([x, y]),
                    body: b.var(selected.name, int),
                }],
                None,
                int,
            )
        };
        let first = select(trace("first", pair));
        let second_core = select(trace("second", pair));
        cases.push((
            format!(
                "two_projections_{}",
                if second { "second" } else { "first" }
            ),
            b.builtin(F::AddInteger, &[first, second_core], int),
            false,
        ));
    }
    for delayed in [false, true] {
        let x = Binder {
            name: b.fresh("x"),
            ty: int,
        };
        let y = Binder {
            name: b.fresh("y"),
            ty: Ty::Const(a.alloc(ConstTy::List(data.ty))),
        };
        let value = b.var(x.name, x.ty);
        let body = if delayed {
            b.delay(value)
        } else {
            b.lam(
                &[Binder {
                    name: b.fresh("arg"),
                    ty: int,
                }],
                value,
            )
        };
        let subject = b.builtin(
            F::UnConstrData,
            &[trace("before failure", data)],
            unwrapped.ty,
        );
        let case = b.case(
            CaseKind::Pair,
            subject,
            &[Branch {
                test: Test::Pair,
                binders: a.alloc([x, y]),
                body,
            }],
            None,
            body.ty,
        );
        let ignored = Binder {
            name: b.fresh("ignored closure"),
            ty: case.ty,
        };
        cases.push((
            format!(
                "unconsumed_{}_failure",
                if delayed { "delay" } else { "lambda" }
            ),
            b.let_(ignored, case, b.int(0)),
            true,
        ));
    }
    for bad_tag in [false, true] {
        for second in [false, true] {
            let tag = Binder {
                name: b.fresh("tag"),
                ty: int,
            };
            let fields_ty = Ty::Const(a.alloc(ConstTy::List(data.ty)));
            let fields = Binder {
                name: b.fresh("fields"),
                ty: fields_ty,
            };
            let encoded = Binder {
                name: b.fresh("encoded"),
                ty: data.ty,
            };
            let decoded = Binder {
                name: b.fresh("decoded"),
                ty: unwrapped.ty,
            };
            let x = Binder {
                name: b.fresh("x"),
                ty: int,
            };
            let y = Binder {
                name: b.fresh("y"),
                ty: fields_ty,
            };
            let selected = if second { y } else { x };
            let body = b.case(
                CaseKind::Pair,
                b.var(decoded.name, decoded.ty),
                &[Branch {
                    test: Test::Pair,
                    binders: a.alloc([x, y]),
                    body: b.var(selected.name, selected.ty),
                }],
                None,
                selected.ty,
            );
            let body = b.let_(
                decoded,
                b.builtin(
                    F::UnConstrData,
                    &[b.var(encoded.name, encoded.ty)],
                    decoded.ty,
                ),
                body,
            );
            let body = b.let_(
                encoded,
                b.builtin(
                    F::ConstrData,
                    &[b.var(tag.name, tag.ty), b.var(fields.name, fields.ty)],
                    encoded.ty,
                ),
                body,
            );
            let body = b.let_(
                fields,
                b.builtin(
                    F::MkCons,
                    &[
                        trace("field", data),
                        b.lit(C::proto_list(a, &Type::Data, &[])),
                    ],
                    fields_ty,
                ),
                body,
            );
            let tag_value = if bad_tag {
                let bytes = b.lit(C::data(a, D::byte_string(a, b"bad")));
                b.with_type(
                    b.builtin(
                        F::UnBData,
                        &[trace("tag", bytes)],
                        b.lit(C::byte_string(a, b"bad")).ty,
                    ),
                    int,
                )
            } else {
                let tag_data = b.lit(C::data(a, D::integer_from(a, 0)));
                b.builtin(F::UnIData, &[trace("tag", tag_data)], int)
            };
            let body = b.let_(tag, tag_value, body);
            cases.push((
                format!(
                    "roundtrip_{}_{}",
                    if bad_tag { "bad_tag" } else { "valid" },
                    if second { "second" } else { "first" }
                ),
                body,
                bad_tag,
            ));
        }
    }
    cases
}

